create table if not exists public.coupon_redemptions(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,coupon_id bigint not null references public.coupons(id) on delete restrict,sale_id bigint not null references public.sales(id) on delete cascade,party_id bigint references public.parties(id) on delete set null,discount_amount numeric(12,2) not null default 0,redeemed_at timestamptz not null default now(),created_by uuid references public.app_users(id) on delete set null);
alter table public.coupon_redemptions enable row level security; revoke all on public.coupon_redemptions from anon,authenticated; grant select,insert,update,delete on public.coupon_redemptions to authenticated;
create policy coupon_redemptions_tenant on public.coupon_redemptions for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create or replace function private.enforce_coupon_redemption_business() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin if not exists(select 1 from coupons c where c.id=new.coupon_id and c.business_id=new.business_id) then raise exception 'coupon does not belong to business'; end if; if not exists(select 1 from sales s where s.id=new.sale_id and s.business_id=new.business_id) then raise exception 'sale does not belong to business'; end if; if new.party_id is not null and not exists(select 1 from parties p where p.id=new.party_id and p.business_id=new.business_id) then raise exception 'party does not belong to business'; end if; if new.discount_amount<0 then raise exception 'invalid discount'; end if; return new; end$$;
revoke all on function private.enforce_coupon_redemption_business() from public,anon,authenticated;
create trigger trg_coupon_redemption_business before insert or update on public.coupon_redemptions for each row execute function private.enforce_coupon_redemption_business();